"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[0,1,2],[1,2,3],[2,3,0],[3,0,1],[0,2,3],[3,1,2]],names=[['Egg','卵'],['Caterpillar','毛毛蟲'],['Chrysalis','蛹'],['Adult butterfly','成蝶']];
let variant=OrionProgress.variant('butterfly'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,chosen=[],solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function correct(list,start=challenge()){return list.length===4&&list.every((n,i)=>n===(start+i)%4);}
function choose(n){if(solved||!Number.isInteger(n)||n<0||n>3||chosen.includes(n)||chosen.length>=4)return;chosen.push(n);state='ready';render();}
function undo(){if(solved||!chosen.length)return;chosen.pop();state='ready';render();}
function resetTrial(){chosen=[];solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('butterfly')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(chosen.length<4)state='incomplete';else if(!correct(chosen))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('renewal');}render();if(solved&&stage<2)$('next').focus();}
function icon(n){const drawings=[`<path d="M12 72Q30 24 102 36Q90 86 12 72" fill="#568e53"/><path d="M18 69L95 40" stroke="#a9c879" stroke-width="2"/><ellipse cx="60" cy="47" rx="14" ry="20" fill="#f1e5bb" stroke="#bcab7a" stroke-width="2"/><path d="M55 30V63M62 28V66M69 32V61" stroke="#cbbd91"/>`,`<path d="M18 76H101" stroke="#6c9b54" stroke-width="5"/>${[25,38,51,64,77].map(x=>`<circle cx="${x}" cy="60" r="12" fill="#83b763" stroke="#456b3c"/><path d="M${x} 70v7" stroke="#d4ba7c" stroke-width="3"/>`).join('')}<circle cx="90" cy="51" r="14" fill="#b7d778"/><circle cx="95" cy="47" r="2" fill="#142d20"/>`,`<path d="M16 15H104" stroke="#a18859" stroke-width="7"/><path d="M60 15V28" stroke="#d2b876" stroke-width="3"/><path d="M60 26Q87 38 74 69L60 89L46 69Q33 38 60 26" fill="#83b997" stroke="#c1d5a3" stroke-width="2"/><path d="M45 45L73 57M44 55L69 69M51 73L64 79" stroke="#557f62"/>`,`<path d="M58 50C15 3 4 37 26 57C6 87 40 103 58 63M62 50C105 3 116 37 94 57C114 87 80 103 62 63" fill="#dbad63" stroke="#514237" stroke-width="4"/><path d="M58 50L28 31M57 58L30 78M62 50L92 31M63 58L90 78" stroke="#665241" stroke-width="3"/><ellipse cx="60" cy="57" rx="5" ry="25" fill="#253e37"/><path d="M58 35L48 23M62 35L72 23" stroke="#d4c49d" stroke-width="2"/>`];return `<svg viewBox="0 0 120 105" aria-hidden="true">${drawings[n]}</svg>`;}
function hints(){const q=challenge();return[t('Look for the stage requested first. What happens next in a butterfly’s life?','先找指定的起點。蝴蝶生命中下一階段是甚麼？'),t('A caterpillar hatches from an egg. Later it becomes a chrysalis, then an adult emerges. Adults reproduce to begin a new generation.','毛毛蟲從卵孵出，之後化蛹，成蝶再羽化而出。成蝶繁殖，開始新一代。'),t('Try this order: ','試試這個次序：')+Array.from({length:4},(_,i)=>t(...names[(q+i)%4])).join(' → ')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Butterfly Conservatory · Orion','蝴蝶秘園 · Orion');$('stageTitle').textContent=t(`Mosaic ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅拼畫 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Garden seals · ${p} / 3`,`花園封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
const order=[2,0,3,1].map(n=>(n+variant+stage)%4);$('cards').innerHTML=order.map(n=>`<button data-stage="${n}" class="${chosen.includes(n)?'chosen':''}" ${solved||chosen.includes(n)?'disabled':''} aria-label="${t('Add ','加入')+t(...names[n])}">${icon(n)}<span>${t(...names[n])}${chosen.includes(n)?' ✓':''}</span></button>`).join('');$('undo').disabled=solved||!chosen.length;
$('goal').textContent=t('Start with: ','起點：')+t(...names[q])+t('. Add all four stages in order.','。依次加入全部四個階段。');$('reading').innerHTML='<div class="cycle-row">'+Array.from({length:4},(_,i)=>`<div class="cycle-slot">${i+1}. ${chosen[i]===undefined?'?':icon(chosen[i])+t(...names[chosen[i]])}${i&&chosen[i]===0&&chosen[i-1]===3?`<small>${t('New generation','新一代')}</small>`:''}</div>`).join('')+'</div>';$('reference').textContent=chosen.length?t('Your order: ','你的次序：')+chosen.map(n=>t(...names[n])).join(' → '):t('Choose a picture to begin.','選擇圖片開始。');const messages={ready:['Explore the order, then restore the mosaic.','探索次序，再修復拼畫。'],incomplete:['Add all four different pictures first.','先加入四張不同的圖片。'],wrong:['Not yet. Check the starting stage and what follows each picture. Clear or undo, then try again.','還未吻合。檢查起點和每張圖片的下一階段。清空或撤回，再試一次。'],success:['The life cycle fits. This mosaic shines!','生命週期吻合了，拼畫亮起來！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('renewal')?t('Renewal Sigil saved in your collection.','蛻變符印已存入收藏。'):'';}
$('cards').onclick=e=>{const b=e.target.closest('button[data-stage]');if(b)choose(Number(b.dataset.stage));};$('undo').onclick=undo;
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('butterfly',variant);observedVariant=OrionProgress.variant('butterfly');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('renewal');render();};function syncProgress(){const v=OrionProgress.variant('butterfly'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('renewal')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
